require_once __DIR__.'/common.php';cron_start('refresh_tokens',900);foreach($db->all("SELECT id FROM youtube_channels WHERE status='connected'") as $r){try{$services->tokenForYoutube((int)$r['id']);}catch(Throwable $e){$services->log('ERROR','oauth.youtube_refresh_failed',$e->getMessage(),['channel_id'=>$r['id']]);$db->exec("UPDATE youtube_channels SET status='error',last_error=?,updated_at=? WHERE id=?",[$e->getMessage(),now_sql(),$r['id']]);}}foreach($db->all("SELECT id FROM google_drive_connections WHERE status='connected'") as $r){try{$services->tokenForDrive((int)$r['id']);}catch(Throwable $e){$services->log('ERROR','oauth.drive_refresh_failed',$e->getMessage(),['drive_id'=>$r['id']]);$db->exec("UPDATE google_drive_connections SET status='error',last_error=?,updated_at=? WHERE id=?",[$e->getMessage(),now_sql(),$r['id']]);}}
